questionvariables.text:
dec(v) := block([k:0], while k<10 and not(integerp(ev(10^k*v,simp))) do k:k+1, if k=0 then string(v) else dispdp(float(v),k));
pad3(r) := if r<10 then sconcat("00",r) else if r<100 then sconcat("0",r) else sconcat(r);
grp(v) := if v<0 then sconcat("-",grp(-v)) else if v<10000 then sconcat(v) else sconcat(floor(v/1000),"\\,",pad3(mod(v,1000)));
money(v) := block([c], c: floor(100*v+1/2), if mod(c,100)=0 then grp(c/100) else sconcat(grp(floor(c/100)),".",if mod(c,100)<10 then sconcat("0",mod(c,100)) else sconcat(mod(c,100))));
/* Design: use an expansion such as (3 + x)^6 to estimate 3.01^6. Source: adapted from SMP AS/A2 Core 4, Chapter 4, Exercise A, question 5. */
L: [[2,1/100,4],[3,-1/100,4],[2,-2/100,6],[3,2/100,3],[2,1/100,7],[3,1/100,5],[2,2/100,5],[3,-2/100,5],[2,-1/100,8],[2,-2/100,3]];
ix: 1+rand(10);
a: L[ix][1];
d: L[ix][2];
n: L[ix][3];
N: a+d;
S4: sum(binomial(n,r)*a^(n-r)*d^r,r,0,3);
noap: a^n+n*d+binomial(n,2)*d^2+binomial(n,3)*d^3;
fact: a^n*sum(binomial(n,r)*d^r,r,0,3);
two: a^n+n*a^(n-1)*d;
C2: binomial(n,2); C3: binomial(n,3);
Nd: dispdp(float(N),2);
dd: dispdp(float(d),2);
rows: makelist([r, binomial(n,r), a^(n-r), dec(d^r), dec(binomial(n,r)*a^(n-r)*d^r)], r, 0, 3);
S4d: dec(S4);
R4: dispdp(float(floor(10^4*S4+1/2)/10^4),4);
calc: dispdp(float(N^n),8);
